function load(){
 try{
  const raw=localStorage.getItem(STORE);if(!raw)return null;
  const p=JSON.parse(raw),base=DEFAULT(),story=ROUTES[p.story]?p.story:'kano';
  const completed=new Set(p.done||[]);
  // Existing V2 runs keep their completed missions; introduce only remaining new incidents.
  if(!p.storyExpansionVersion)EXTRA_STOPS[story].forEach(([id,km])=>{if(km<(p.km||0))completed.add(id)});
  if((p.storyExpansionVersion||0)<3)ROAD_STOPS[story].forEach(([id,km])=>{if(km<(p.km||0))completed.add(id)});
  if((p.storyExpansionVersion||0)<4)MOBILITY_STOPS[story].forEach(([id,km])=>{if(km<(p.km||0))completed.add(id)});
  return {...base,...p,story,accident:!!p.accident,collisionProtection:0,docs:{...base.docs,...p.docs},speed:0,autoDrive:false,steerPos:typeof p.steerPos==='number'?p.steerPos:0,junctionsCleared:p.junctionsCleared||[],done:[...completed],storyExpansionVersion:4,warningLog:p.warningLog||[],vehicleFaults:p.vehicleFaults||{}};
 }catch(_){return null}
}
