 const deposit=Math.round(price*.25),principal=price-deposit,months=36,rate=.15,payment=loanMonthly(principal,rate,months);
 showModal({kicker:'GREENREV • FINANCE SIMULATOR',emoji:'🏦',title:'Financing your '+c.name,description:'Compare a fictional 25% deposit and 36 monthly instalments. These are illustrative calculations, not a real loan offer, credit assessment, APR quote or bank partnership.',content:`<div class="modal-detail">Vehicle: <b>${fmt(price)}</b><br>Deposit: <b>${fmt(deposit)}</b> (25%)<br>Financed balance: <b>${fmt(principal)}</b><br>Illustrative annual nominal interest: <b>15%</b><br>36 estimated monthly payments: <b>${fmt(payment)}</b><br>Approximate total payable: <b>${fmt(deposit+36*payment)}</b><br>Demo wallet: <b>${fmt(state.wallet)}</b><br><small>No money is borrowed and no real-world finance contract exists.</small></div>`,actions:[
 {text:'Approve demo finance & buy',run:()=>{if(state.wallet<deposit)return showInsufficient(deposit,()=>financeVehicle(c,price));state.wallet-=deposit;state.financing={car:c.id,price,deposit,monthly:payment,months,remaining:36,principal,rate};state.carBought=c.id;state.powertrain=c.powertrain;state.fuel=100;state.health=100;state.bankLedger.unshift({kind:'Demo vehicle-finance deposit',amount:-deposit,at:new Date().toISOString()});save();complete('dealer',c.name+' financed (simulation).',190,140)}},
 {text:'Back to dealership',style:'subtle',run:showCarChoices}]});
