const CHECKOUT_PACKAGES=[{credit:5000000,charge:100},{credit:25000000,charge:250},{credit:100000000,charge:500}];
function startHostedCheckout(credit){
 const pack=CHECKOUT_PACKAGES.find(p=>p.credit===credit);
 if(!pack)return toast('Unknown test package.','warn');
 showModal({kicker:'PAYSTACK HOSTED CHECKOUT • TEST MODE',emoji:'💳',title:'Connect to the payment provider',description:`The checkout charges ${fmt(pack.charge)} in Paystack TEST MODE and awards ${fmt(pack.credit)} simulation-only game credits after verified success. No real money is taken with test keys.`,
 content:`<label class="phone-label" for="checkoutEmail">Email for test payment</label><input id="checkoutEmail" type="email" autocomplete="email" placeholder="you@example.com" maxlength="160" value="tester@example.com" /><div class="modal-detail">🔒 Card/bank details are entered ONLY on Paystack's hosted page.<br>Test checkout requires a local Node server and your own <code>sk_test_</code> secret.<br>Never enter live banking details during this prototype test.</div>`,
 actions:[{text:'↗ Continue to Paystack test checkout',run:async()=>{
  const email=$('checkoutEmail')?.value.trim();if(!email||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return toast('Enter a valid email.','warn');
  const button=$('modalActions')?.querySelector('button');if(button){button.disabled=true;button.textContent='Connecting to Paystack…'}
  try{let ready;
   try{const c=await fetch('/api/config',{cache:'no-store'});ready=await c.json();if(!c.ok||ready.provider!=='Paystack')throw Error('wrong server');}
   catch(_){throw Error('Payment backend not running: launch START-GAME-WINDOWS.bat or use node server.js (not VS Code Live Server).')}
   if(!ready.configured)throw Error('Paystack TEST key missing. Copy .env.example to .env, add your sk_test_ key, restart node server.js.');
   const r=await fetch('/api/payments/initialize',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,credit})});const j=await r.json();if(!r.ok)throw Error(j.error||'Checkout is not configured');
   if(!/^https:\/\/checkout\.paystack\.com\//.test(j.checkout_url))throw Error('Invalid hosted-checkout URL.');
   window.location.assign(j.checkout_url);
  }catch(e){toast(e.message,'warn');if(button){button.disabled=false;button.textContent='↗ Continue to Paystack test checkout'} }
 }},{text:'Return to virtual wallet',style:'subtle',run:showBank}]});
}
async function verifyHostedReturn(){
 const params=new URLSearchParams(location.search),reference=params.get('reference')||params.get('trxref');
 if(!reference)return;
 history.replaceState(null,'',location.pathname+location.hash);
 if(!/^[A-Za-z0-9._=-]{6,120}$/.test(reference))return toast('Invalid checkout reference.','warn');
 if(state.creditedRefs.includes(reference)){toast('This test payment has already been applied.');return;}
 try{const r=await fetch('/api/payments/verify?reference='+encodeURIComponent(reference));const data=await r.json();if(!r.ok||!data.verified)throw Error(data.error||'Payment not confirmed');
  if(state.creditedRefs.includes(reference))return;
  state.creditedRefs.push(reference);state.wallet+=data.credit;state.bankLedger.unshift({kind:'Paystack-verified TEST payment',amount:data.credit,at:new Date().toISOString(),reference});
  save();updateAll();renderPhone();showModal({kicker:'PAYSTACK • TEST PAYMENT VERIFIED',emoji:'✅',title:fmt(data.credit)+' added to game wallet',description:'Your server verified a successful Paystack test transaction, matching the transaction amount and reference. This is not a live-money payment.',actions:[{text:'Open wallet',run:showBank},{text:'Resume game',style:'subtle',run:hideModal}]});
 }catch(e){showModal({kicker:'CHECKOUT VERIFICATION',emoji:'⚠️',title:'Virtual credits not applied',description:'The server could not verify this Paystack test payment: '+String(e.message),actions:[{text:'Open wallet',run:showBank}]})}
}
