function done(id){return state.done.includes(id)}
function nextEvent(){return EVENTS.find(ev=>!done(ev.id))}
function complete(id, message, xp=100,points=50){if(done(id))return;state.done.push(id);state.currentEvent=null;state.speed=0;state.autoDrive=false;state.trust=clamp(state.trust+6,0,100);earn(xp,points);if(id==='arrival'){state.tripComplete=true;state.endedAt=new Date().toISOString();}else if(state.resumeCruise){state.autoDrive=true;state.resumeCruise=false;}save();hideModal();toast(message+'  +'+xp+' XP  +'+points+' GreenPoints');updateAll();if(id==='arrival')setTimeout(()=>showEnding(),600)}
function closestWaypoint(){let result=WAYPOINTS[0];for(const p of WAYPOINTS)if(state.km>=p.km)result=p;return result}
function locationFor(km){const a=routeInfo().places;let n=a[0];for(const place of a)if(km>=place.km)n=place;return n.name.replace(' OUTSKIRTS','').replace(' ROAD','').replace(' HIGHWAY','')}
function toast(text,type='normal'){let host=$('toasts');const d=document.createElement('div');d.className='toast';d.textContent=(type==='warn'?'⚠ ':'✦ ')+text;host.append(d);setTimeout(()=>{d.remove()},4200)}
function updateAll(){const lvl=Math.floor(state.xp/100)+1;$('profileName').textContent=state.name;$('avatarEmoji').textContent=state.avatar;$('levelText').textContent=lvl;$('xpText').textContent=state.xp+' XP';$('xpFill').style.width=(state.xp%100)+'%';$('walletText').textContent=fmt(state.wallet);$('pointsText').textContent=state.points;$('trustText').textContent=state.trust+' / 100';$('distanceText').textContent=Math.floor(state.km)+' / '+ROUTE_LENGTH+' km';$('healthText').textContent=Math.round(state.health)+'%';$('fuelText').textContent=Math.round(state.fuel)+'%';const fuelLabel=$('fuelLabel');if(fuelLabel)fuelLabel.textContent=state.powertrain==='electric'?'BATTERY':'FUEL';$('speedText').textContent=Math.round(state.speed);$('elapsedText').textContent=formatDuration(state.tripElapsedMs);$('timeStatus').textContent=state.tripComplete?'ARRIVED • '+localClock(state.endedAt):state.hasStarted?'STARTED • '+localClock(state.startedAt):'READY TO DEPART';$('npcAvatar').textContent=state.currentEvent?({police:'👮🏾',breakdown:'👨🏾‍🔧',parts:'👩🏾‍🔧',rest:'👩🏾‍🍳',vio:'👮🏽',dealer:'👨🏿‍💼',passport:'🧑🏽‍💻',rental:'👩🏾‍💼',haulage:'👷🏾‍♂️',courier:'🚚',seller:'👨🏾‍💼',tyre:'👩🏾‍🔧',dashboard:'👨🏾‍🔧',weather:'👮🏾',battery:'🧑🏾‍🔧',brakes:'👩🏾‍🔧'}[state.currentEvent]||state.avatar):state.avatar;$('npcName').textContent=state.currentEvent?({police:'ROAD SAFETY OFFICER',breakdown:'MOBILE MECHANIC',parts:'SPARE PARTS SELLER',rest:'REST AREA ATTENDANT',vio:'VIO OFFICER',dealer:'CAR DEALER',passport:'PASSPORT INSPECTOR',rental:'RENTAL HOST',haulage:'LOGISTICS DISPATCH',courier:'PARTS COURIER',seller:'DEALER SUPPORT',tyre:'TYRE TECHNICIAN',dashboard:'DASHBOARD ASSISTANT',weather:'ROAD SAFETY ADVISOR',battery:'AUTO ELECTRICIAN',brakes:'BRAKE TECHNICIAN'}[state.currentEvent]||'GREENREV'):state.name.toUpperCase();$('npcSpeech').textContent=state.currentEvent?'Use your GreenRev phone to continue.':state.tripComplete?'Welcome to '+routeInfo().destination+'!':state.speed>5?'Oya, enjoy the journey!':'Use ↑ / WASD or press GAS.';$('journeyFill').style.width=(state.km/ROUTE_LENGTH*100)+'%';$('journeyCar').style.left='calc('+clamp(state.km/ROUTE_LENGTH*100,0,99)+'% - 5px)';$('locationText').textContent=locationFor(state.km).toUpperCase();$('sceneSubtitle').textContent=closestWaypoint().subtitle;$('carName').textContent=state.carBought? (CARS.find(c=>c.id===state.carBought)?.name||'Upgraded vehicle')+' • '+(state.powertrain==='electric'?'electric':'petrol'):'Toyota Corolla • 2012';$('tripStatus').textContent=state.tripComplete?'CHAMPION 🏆':state.currentEvent?'ATTENTION NEEDED':'ON THE ROAD';$('pauseLabel').hidden=!state.currentEvent&&!state.accident;
 $('pauseLabel').textContent=state.accident?'⚠ COLLISION • VEHICLE STOPPED':state.currentEvent?'STORY EVENT • PULL OVER':'';
 const resume=$('btnResumeEvent');resume.hidden=!state.currentEvent&&!state.accident;
 if(!resume.hidden)resume.textContent=state.accident?'⚠ Open crash recovery':state.currentEvent==='dealer'?'🚗 Continue car purchase':'▶ Continue '+(eventAt(state.currentEvent)?.title||'mission');
 $('canvasShell').classList.toggle('is-crashed',!!state.accident);
 $('sceneTitle').textContent=routeInfo().title;
 $('routeOrigin').textContent=routeInfo().origin;$('routeDestination').textContent=routeInfo().destination;
 $('routeTopOrigin').textContent=routeInfo().origin;$('routeTopDestination').textContent=routeInfo().destination;
 $('btnStories').textContent='🗺️ '+(state.story==='kano'?'Kano Quest':'Lagos → Abuja');if($('serviceQuestMeter'))$('serviceQuestMeter').textContent=EVENTS.filter(e=>EXTRA_MISSIONS[e.id]&&done(e.id)).length+'/5 services';
 $('tripStatus').textContent=state.accident?'⚠ CRASH • RECOVERY':state.tripComplete?'CHAMPION 🏆':state.currentEvent?'MISSION PAUSED':'ON THE ROAD';
$('canvasShell').classList.toggle('resting',state.currentEvent==='rest');const plaza=$('restPlazaMenu');if(plaza){plaza.hidden=state.currentEvent!=='rest';$('restContinue').disabled=!(state.restMeal&&state.restConvenience)}const steering=$('steeringText');if(steering){const pct=Math.round(Math.abs(state.steerPos)*75);steering.textContent=Math.abs(state.steerPos)<.06?'CENTRE':(state.steerPos<0?'LEFT ':'RIGHT ')+pct+'%';$('steeringMarker').style.left=(50+clamp(state.steerPos,-1.2,1.2)*38)+'%'}$('btnCruise').textContent=state.autoDrive?'❚❚ Stop auto-drive':state.accident||state.currentEvent?'▶ Resume story':'▶ Auto-drive';const outstanding=EVENTS.filter(e=>done(e.id)).length;
 const visibleCars=traffic.filter(t=>t.distance>-25&&t.distance<170).length;const buses=traffic.filter(t=>(t.kind==='danfo'||t.kind==='hiace')&&t.distance>-25&&t.distance<170).length;const trafficCount=$('trafficCount');if(trafficCount)trafficCount.textContent=visibleCars+' moving vehicles · '+buses+' buses';
 const alert=$('vehicleWarning');if(alert){const danger=state.currentEvent&&ROAD_MISSIONS[state.currentEvent];alert.hidden=!danger;alert.textContent=danger?ROAD_MISSIONS[state.currentEvent][1]+' '+ROAD_MISSIONS[state.currentEvent][0].toUpperCase():'';}$('questCount').textContent=outstanding+'/'+EVENTS.length;$('questList').innerHTML=EVENTS.map(ev=>`<div class="quest ${done(ev.id)?'done':''} ${nextEvent()?.id===ev.id?'active':''}"><span class="quest-icon">${done(ev.id)?'✓':ev.icon}</span><div><strong>${escapeHtml(ev.title)}</strong><p>${escapeHtml(ev.detail)}</p></div>${nextEvent()?.id===ev.id?'<span class="quest-flag">●</span>':''}</div>`).join('');const current=nextEvent();$('objectiveTitle').textContent=state.currentEvent?current?.title||'Road safety':'Next up: '+(current?.title||'Completed!');$('objectiveText').textContent=state.accident?'Your car needs recovery before you can continue.':state.currentEvent?(current?.detail||'')+' • Click Continue current story event below.':current?`Drive to km ${current.km} or jump to test this scene.`:'All '+EVENTS.length+' '+routeInfo().title+' missions completed.';$('storyIcon').textContent=current?.icon||'🏆';$('btnOpenRelevant').textContent=state.accident?'Open crash recovery ↗':state.currentEvent?'Continue current mission ↗':'Open phone ↗';$('btnNextScene').disabled=state.tripComplete;$('btnNextScene').textContent=state.accident?'⚠ Crash recovery':state.currentEvent?'▶ Continue current story event':'⚡ Jump to next story event';const relevant={police:'documents',breakdown:'mechanics',parts:'parts',rest:'home',vio:'documents',dealer:'cars',passport:'services',rental:'services',haulage:'services',courier:'services',seller:'dealer',arrival:'home'};$('btnOpenRelevant').dataset.goto=relevant[current?.id]||'home';}
function formatDuration(ms){const sec=Math.floor((ms||0)/1000);return [Math.floor(sec/3600),Math.floor(sec/60)%60,sec%60].map(n=>String(n).padStart(2,'0')).join(':')}
function localClock(v){return v?new Date(v).toLocaleTimeString('en-NG',{hour:'2-digit',minute:'2-digit',second:'2-digit'}):'—'}
function escapeHtml(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function phoneTab(tab){activeTab=tab;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));renderPhone();}
function showModal(opts){currentModal=opts;modalDismissible=opts.dismiss!==false;$('modalLayer').hidden=false;$('modalKicker').textContent=opts.kicker||'GREENREV STORY';$('modalEmoji').textContent=opts.emoji||'🚙';$('modalTitle').textContent=opts.title||'';$('modalDescription').textContent=opts.description||'';$('modalContent').innerHTML=opts.content||'';$('modalActions').innerHTML=(opts.actions||[]).map((a,i)=>`<button type="button" class="button ${a.style||''}" data-modal-action="${i}">${escapeHtml(a.text)}</button>`).join('');$('modalActions').querySelectorAll('[data-modal-action]').forEach((b,i)=>b.addEventListener('click',()=>{const action=opts.actions?.[i];if(action)action.run()}));$('modalClose').hidden=!modalDismissible;}
function hideModal(){currentModal=null;$('modalLayer').hidden=true;if(document.activeElement?.closest?.('#modalLayer'))document.activeElement.blur();}
$('modalClose').onclick=()=>{if(modalDismissible)hideModal()};document.querySelector('.modal-backdrop').onclick=()=>{if(modalDismissible)hideModal()};
function openEvent(id){state.currentEvent=id;state.autoDrive=false;state.speed=0;save();updateAll();if(id==='police')return showPolice();if(id==='breakdown')return showBreakdown();if(id==='parts')return showPartsIncident();if(id==='rest')return showRestStop();if(id==='vio')return showVio();if(id==='dealer')return showDealerMission();if(id==='passport')return showPassport();if(id==='rental')return showRental();if(id==='haulage')return showHaulage();if(id==='courier')return showCourier();if(id==='seller')return showSellerMission();if(id==='tyre')return showTyreMission();if(id==='dashboard')return showDashboardMission();if(id==='weather')return showWeatherMission();if(id==='battery')return showBatteryMission();if(id==='brakes')return showBrakeMission();if(id==='service')return showServicePlaza();if(id==='danfo')return showDanfoEncounter();if(id==='charging')return showChargeStop();if(id==='arrival')return complete('arrival','You reached '+routeInfo().destination+'! Mission accomplished.',200,150)}
function startEventWhenReady(){if(state.currentEvent||state.tripComplete)return;const n=nextEvent();if(n&&state.km>=n.km){state.km=n.km;openEvent(n.id)}}
function showPolice(){phoneTab('documents');showModal({kicker:`ROADBLOCK • KM ${eventAt('police').km}`,emoji:'🚔',title:'Officer: "Good afternoon, driver!"',description:'You are approaching a routine FRSC/police checkpoint. An officer requests your driving licence, vehicle registration and motor insurance evidence. Respectful conversation; no bribes.',content:'<div class="modal-detail"><b>OFFICER:</b> "Driver, please park safely and show me your papers. We need to verify that your vehicle is road legal."</div>',actions:[{text:'📋 Present my papers',run:showPoliceScan},{text:'Open documents in GreenRev',style:'subtle',run:()=>{hideModal();phoneTab('documents')}}]})}
function showPoliceScan(){const all=state.docs.licence&&state.docs.registration&&state.docs.insurance;showModal({kicker:'DIGITAL DOCUMENT CHECK',emoji:all?'✅':'🪪',title:all?'Your papers check out!':'Your insurance has expired',description:all?'The officer checks the documents and thanks you for cooperating.':'The digital record shows your vehicle insurance needs renewal. Open GreenRev Papers to update this simulated record before proceeding.',content:`<div class="modal-detail"><div class="check-item">🪪 Driver's licence <span>${state.docs.licence?'✅ VALID':'❌'}</span></div><div class="check-item">📗 Vehicle registration <span>${state.docs.registration?'✅ VALID':'❌'}</span></div><div class="check-item">🛡️ Motor insurance <span>${state.docs.insurance?'✅ VALID':'❌ EXPIRED'}</span></div></div>`,actions:all?[{text:'Thank officer & continue +100 XP',run:()=>complete('police','Checkpoint cleared!')}]:[{text:'Renew insurance in GreenRev',run:()=>{hideModal();phoneTab('documents')}},{text:'Recheck papers',style:'subtle',run:showPoliceScan}]})}
function showBreakdown(){state.health=34;phoneTab('mechanics');updateAll();showModal({kicker:`ROADSIDE EMERGENCY • KM ${eventAt('breakdown').km}`,emoji:'🌡️',title:'Your temperature gauge is in the red!',description:'Steam rises from your engine bay. Pull over, stop the engine and use GreenRev to diagnose the fault, arrange mobile repairs or request a tow. Do not open a hot radiator.',content:'<div class="modal-detail">Possible causes: coolant hose • thermostat • radiator fan<br>Vehicle health: 34%<br>Location: '+escapeHtml(nearbyCity('breakdown'))+'</div>',actions:[{text:'📱 Compare 5 nearby mechanics',run:()=>{hideModal();phoneTab('mechanics')}},{text:'🧠 Diagnose warning and choose service',run:showMechanicOptions},{text:'🚚 Book recovery • ₦20,000',style:'subtle',run:()=>{if(!spend(20000))return;state.health=70;showModal({kicker:'GREENREV RECOVERY',emoji:'🚚',title:'Vehicle transported to a partner garage',description:'A fictional tow truck carries your vehicle to a workshop. You still need to complete the repair.',actions:[{text:'Choose workshop',run:()=>{hideModal();phoneTab('mechanics')}}]})}}]})}
function showMechanicOptions(){showModal({kicker:'GREENREV SERVICE ADVISOR',emoji:'🛠️',title:'Choose the right automotive help',description:'A few Nigerian roadside repair scenarios. Always stop driving when the car is unsafe.',content:'<div class="modal-detail">🌡️ Engine heat: coolant leak or fan issue<br>🛞 Tyre: puncture or low pressure<br>🛑 Brakes: spongy pedal or warning light<br>🔋 Electrical: flat battery / alternator<br>❄️ AC: air conditioning service<br>⚡ EV: high-voltage system — certified technician only</div>',actions:[{text:'🌡️ Cooling system service',run:()=>{hideModal();phoneTab('mechanics')}},{text:'🛞 Tyres and brakes',run:()=>showPaidService('Tyre, brake and alignment inspection',14500,12)},{text:'🔋 Battery and alternator',run:()=>showPaidService('Battery / alternator diagnostic',11500,9)},{text:'❄️ Air conditioning',run:()=>showPaidService('AC cabin and refrigerant assessment',17500,8)},{text:'⚡ Hybrid / electric vehicle check',run:()=>showPaidService('Certified EV diagnostic inspection',22500,12)}]})}
function showPaidService(label,fee,health){showModal({kicker:'GREENREV VERIFIED SERVICE • DEMO',emoji:'🔧',title:label,description:'Choose a simulated garage appointment and pay with game credits. This is an extra non-mission vehicle-care interaction.',content:`<div class="modal-detail">Service: ${escapeHtml(label)}<br>Quote: <b>${fmt(fee)}</b><br>Car-health improvement: +${health}<br>Provider verification is only fictional.</div>`,actions:[{text:'Confirm and pay '+fmt(fee),run:()=>{if(!spend(fee))return;state.health=clamp(state.health+health,0,100);state.serviceHistory.push({kind:label,amount:fee,at:locationFor(state.km)});earn(20,10);save();hideModal();updateAll();toast(label+' completed.')}},{text:'See other repair options',style:'subtle',run:showMechanicOptions}]})}
function callMechanic(id){const m=MECHANICS.find(x=>x.id===id);if(!m)return;state.mechanicId=id;state.mechanicChat=[{from:'them',text:`Hello! ${m.name} here. I can come to your location near ${nearbyCity('breakdown')} in about ${m.eta} minutes (game time). What seems wrong?`}];save();phoneTab('mechanics');showModal({kicker:'IN-APP CALL • GREENREV',emoji:'📞',title:`Connected to ${m.name}`,description:'You explain that the car overheated and stopped. The mechanic shares an estimate. Negotiate the service price or accept the quote.',content:`<div class="modal-detail"><b>MECHANIC:</b> "No wahala. I can come with tools and inspect the cooling hose. The total estimated labour and replacement is <b>${fmt(m.price)}</b>. Shall I come?"</div>`,actions:[{text:`Book for ${fmt(m.price)}`,run:()=>bookMechanic(m.price)},{text:'🤝 Negotiate a better price',style:'orange',run:()=>negotiateMechanic(m)},{text:'Pick a different mechanic',style:'subtle',run:()=>{hideModal();phoneTab('mechanics')}}]})}
function negotiateMechanic(m){const revised=Math.max(11000,m.price-3000);showModal({kicker:'NEGOTIATION',emoji:'🤝',title:'A better deal. Oya!',description:`You respectfully negotiate and ${m.name} offers ${fmt(revised)} for the complete job. All service quotes here are fictional.`,content:`<div class="modal-detail">"I understand, boss. I can do <b>${fmt(revised)}</b> if we proceed now. You'll confirm the job is done before payment."</div>`,actions:[{text:`Accept ${fmt(revised)}`,run:()=>bookMechanic(revised)},{text:'Choose another mechanic',style:'subtle',run:()=>{hideModal();phoneTab('mechanics')}}]})}
function bookMechanic(price){if(state.wallet<price)return toast('Insufficient game wallet!','warn');state.repairPrice=price;state.quoteAccepted=true;state.repairStep=0;save();repairMinigame()}
const REPAIR_STEPS=[{title:'Step 1: Diagnose',text:'The mechanic scans the engine bay and identifies a leaking coolant hose. Tap to confirm the diagnostic step.',emoji:'🔍',action:'Inspect the cooling system'},{title:'Step 2: Replace part',text:'The faulty hose is replaced with a compatible spare and coolant is replenished.',emoji:'🔧',action:'Fit replacement hose'},{title:'Step 3: Final check',text:'Run a safe engine test and confirm no coolant leaks remain.',emoji:'✅',action:'Test engine & verify repair'}];
function repairMinigame(){const s=REPAIR_STEPS[state.repairStep];if(!s){showModal({kicker:'SERVICE CONFIRMATION',emoji:'🙌',title:'Your engine is running smoothly!',description:'The mechanic has finished. Confirm that the issue has been resolved, then release the demo payment for the service.',content:`<div class="modal-detail">🧾 <b>Job:</b> Cooling system repair<br>💰 <b>Approved quote:</b> ${fmt(state.repairPrice)}<br>🔐 <b>Payment status:</b> Pending your confirmation</div>`,actions:[{text:`Confirm & pay ${fmt(state.repairPrice)}`,run:()=>{if(!spend(state.repairPrice))return;state.health=100;state.fuel=clamp(state.fuel+15,0,100);state.quoteAccepted=false;state.repairStep=0;state.mechanicChat=[];complete('breakdown','Rescued on the road! Mechanic paid. ',140,85)}},{text:'Review work again',style:'subtle',run:()=>{state.repairStep=2;repairMinigame()}}]});return}
showModal({kicker:`SERVICE IN PROGRESS • ${state.repairStep+1}/3`,emoji:s.emoji,title:s.title,description:s.text,content:`<div class="modal-detail">${REPAIR_STEPS.map((v,i)=>`${i<state.repairStep?'✅':i===state.repairStep?'🟢':'⚪'} ${v.title}`).join('<br>')}</div>`,actions:[{text:s.action,run:()=>{state.repairStep++;save();repairMinigame()}}]})}
function showPartsIncident(){phoneTab('parts');showModal({kicker:`PARTS CHALLENGE • KM ${eventAt('parts').km}`,emoji:'💡',title:'One of your headlights has gone out!',description:'As evening draws near, your left headlight stops working. Find a correctly fitting replacement via GreenRev Parts. Choose carefully: not every headlight fits your car.',content:'<div class="modal-detail">🚙 Toyota Corolla 2012<br>🔦 <b>Required:</b> H4 compatible replacement<br>📍 Along this road<br>⚠️ Do not continue driving in darkness with defective lighting.</div>',actions:[{text:'Browse compatible car parts',run:()=>{hideModal();phoneTab('parts')}}]})}
function buyPart(id){const p=PARTS.find(x=>x.id===id);if(!p)return;if(id==='wrong'){toast('Fitment warning: H7 is not compatible with this Corolla.','warn');showModal({kicker:'GREENREV FITMENT CHECK',emoji:'🚫',title:'Not the right fit!',description:'GreenRev checks the car model and warns before you buy an incompatible product. Choose an H4 headlight for Toyota Corolla 2012.',actions:[{text:'Return to compatible parts',run:()=>{hideModal();phoneTab('parts')}}]});return}showModal({kicker:'MARKETPLACE • DEMO CHECKOUT',emoji:'🛒',title:'Ready to order your headlight?',description:`${p.name} from ${p.seller}. This is an entirely simulated transaction with demo currency.`,content:`<div class="modal-detail">✓ Vehicle fit verified<br>✓ Seller details displayed<br>✓ Pickup available at roadside partner<br><b>Total: ${fmt(p.price)}</b></div>`,actions:[{text:`Pay ${fmt(p.price)} (demo)`,run:()=>{if(!spend(p.price))return;state.partsPurchased.push(id);save();showPartFit(p)}},{text:'Keep browsing',style:'subtle',run:()=>{hideModal();phoneTab('parts')}}]})}
function showPartFit(p){showModal({kicker:'ORDER READY FOR PICKUP',emoji:'📦',title:'Your replacement headlight has arrived',description:`Your ${p.name} is handed over at a nearby partner location. A technician fits it and you test both beams.`,content:'<div class="modal-detail">📍 Pickup confirmed<br>📦 Authenticity/fitment: <b>Verified in simulation</b><br>🧾 Order: GR-PART-2048</div>',actions:[{text:'Fit headlight & test it',run:()=>complete('parts','Headlight replaced. Good visibility!',120,75)}]})}
