 showModal({kicker:'NIGERIAN EXPRESSWAY • FOOD COURT',emoji:'🍲',title:'What will you chop?',description:'Choose from a variety of Nigerian food vendors. Each price is fictional and uses only the demo wallet.',content:`<div class="modal-detail">${EXPRESSWAY_MEALS.map(m=>`${m.emoji} ${escapeHtml(m.name)} — <b>${fmt(m.price)}</b>`).join('<br>')}</div>`,actions:[...EXPRESSWAY_MEALS.map(m=>({text:`${m.emoji} ${m.name} • ${fmt(m.price)}`,run:()=>{if(!spend(m.price))return;state.restMeal=m.name;state.health=clamp(state.health+Math.round(m.energy/3),0,100);earn(12,6);save();toast('Oya! '+m.name+' served.');returnFn()}})),{text:'Not hungry',style:'subtle',run:returnFn}]});
